 UIStackView *stack=[UIStackView new]; stack.axis=UILayoutConstraintAxisVertical; stack.spacing=16; stack.layoutMargins=UIEdgeInsetsMake(22,20,28,20); stack.layoutMarginsRelativeArrangement=YES; stack.translatesAutoresizingMaskIntoConstraints=NO; [scroll addSubview:stack];
 [NSLayoutConstraint activateConstraints:@[[stack.topAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.topAnchor],[stack.bottomAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.bottomAnchor],[stack.leadingAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.leadingAnchor],[stack.trailingAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.trailingAnchor],[stack.widthAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.widthAnchor]]];
 [stack addArrangedSubview:[Theme label:@"cha0s" size:38 weight:UIFontWeightHeavy color:Theme.text]]; [stack addArrangedSubview:[Theme label:@"IOS SYSTEM RESEARCH TOOLKIT" size:11 weight:UIFontWeightBold color:Theme.mint]];
